L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "\227\129\130\227\128\129\232\166\129\228\186\186\227\129\174\233\161\148\227\129\164\227\129\141\227\130\132\230\156\141\232\163\133\227\128\129\229\160\180\230\137\128\227\129\171\227\129\164\227\129\132\227\129\166\227\129\175\227\129\169\227\129\134\228\188\157\227\129\136\227\129\190\227\129\153\227\129\139\239\188\159"
