L8_1 = "Oh, and what should I tell her about this VIP, as far as his appearance and location go?"
L7_1.m_Talk_ENG = L8_1
L8_1 = "\228\184\141\233\129\142\239\188\140\232\166\129\229\147\161\231\154\132\231\169\191\232\145\151\233\149\183\231\155\184\229\146\140\228\189\141\231\189\174\232\166\129\230\128\142\233\186\188\232\170\170\229\149\138\239\188\159"
