L7_1.m_Talk_VTN = L8_1
L8_1 = "\229\149\138\239\188\140\233\156\128\232\166\129\229\175\185\232\166\129\229\145\152\231\154\132\232\161\163\231\157\128\231\155\184\232\178\140\229\146\140\228\189\141\231\189\174\228\191\161\230\129\175\232\191\155\232\161\140\229\133\183\228\189\147\232\175\180\230\152\142\228\185\136\239\188\159"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Oh\194\160\226\128\147 und was soll ich ihr sagen, wie dieser VIP aussieht und wo er sich befindet?"
